#include <stdio.h>
#include <stdlib.h>

int main() {
    int array1[] = {1, 2, 3, 4, 5};
    int array2[] = {2, 3, 4, 5, 6};
    int i, j, common;

    for (i = 0; i < 5; i++) {
        for (j = 0; j < 5; j++) {
            if (array1[i] == array2[j]) {
                common = i;
                break;
            }
        }
        if (common != -1) {
            printf("Common element: %d\n", common);
            break;
        }
    }

    return 0;
}
```
